import{_ as d,C as o,o as s,c as l,j as e,a as c,E as i,a6 as a}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"03 · Repeatable Readiness Engagement Scope","description":"Turnkey intake qualification scorecard and 3-week structured delivery blueprint for scoping proactive Foundry model migration & PTU readiness engagements.","frontmatter":{"title":"03 · Repeatable Readiness Engagement Scope","description":"Turnkey intake qualification scorecard and 3-week structured delivery blueprint for scoping proactive Foundry model migration & PTU readiness engagements."},"headers":[],"relativePath":"operating-model/delivery-scoping.md","filePath":"operating-model/delivery-scoping.md","lastUpdated":1795280666087}'),g={name:"operating-model/delivery-scoping.md"};function p(f,t,u,h,y,m){const r=o("PageBrief"),n=o("IntakeScorecard");return s(),l("div",null,[t[0]||(t[0]=e("h1",{id:"_03-·-repeatable-readiness-engagement-scope",tabindex:"-1"},[c("03 · Repeatable Readiness Engagement Scope "),e("a",{class:"header-anchor",href:"#_03-·-repeatable-readiness-engagement-scope","aria-label":'Permalink to "03 · Repeatable Readiness Engagement Scope"'},"​")],-1)),i(r,{stepLabel:"PROACTIVE DELIVERY · 03",readTime:"4 min read",problem:"Proactive readiness work stalls without a fast qualification filter and a bounded week-by-week delivery plan.",takeaway:"Qualify exposure in 30 minutes using 6 boundary questions, then execute a structured 3-week engagement with concrete exit artifacts.",csaUse:"Run the interactive scorecard below during a 30-minute discovery session, toggle the workload traits, and copy the scope summary."}),t[1]||(t[1]=a('<p>A core goal of Solution Industrialization is making architecture patterns <strong>immediately scopable as repeatable proactive delivery engagements</strong>. Use the interactive multi-track triage tool below (also available in the <a href="/enterprise-azure-ai-hub/studio/#triage">Interactive Decision Studio</a>) and the 3-week blueprint to scope a <strong>Microsoft Foundry Production Readiness Engagement</strong> across <a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/start/01-executive-thesis">Playbook 01 (Caching &amp; PTU)</a>, <a href="/enterprise-azure-ai-hub/playbooks/apim-gateway/01-executive-thesis">Playbook 02 (APIM AI Gateway)</a>, <a href="/enterprise-azure-ai-hub/playbooks/multi-region-bcp/01-executive-thesis">Playbook 03 (Multi-Region BCP)</a>, and <a href="/enterprise-azure-ai-hub/playbooks/agentic-rag-evals/01-executive-thesis">Playbook 04 (Agentic Harness &amp; Evals)</a>.</p><h2 id="_1-intake-qualification-scorecard" tabindex="-1">1. Intake Qualification Scorecard <a class="header-anchor" href="#_1-intake-qualification-scorecard" aria-label="Permalink to &quot;1. Intake Qualification Scorecard&quot;">​</a></h2>',2)),i(n),t[2]||(t[2]=a('<p>Capture <strong>orders of magnitude and architectural boundaries</strong> during a 30-minute intake call—not false precision:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Qualification Dimension</th><th style="text-align:left;">Discovery Question</th><th style="text-align:left;">Architectural Branch Triggered</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Migration Trigger &amp; Timeline</strong></td><td style="text-align:left;">Which retiring or baseline models (<code>gpt-4o</code>, <code>gpt-4.1</code>, <code>o3-mini</code>, <code>gpt-5.4</code>) are migrating to <code>gpt-5.6</code>, <code>gpt-6</code>, or <code>gpt-6.1</code>, and what is the cutover date?</td><td style="text-align:left;">Determines whether pre-GPT-6 (<code>0%</code> cached PTU draw, <code>6x</code> output) or GPT-6/6.1 normalized weights (<code>0.1x</code>/<code>0.05x</code> read, <code>1.25x</code> write, <code>5.0x</code> output) govern sizing.</td></tr><tr><td style="text-align:left;"><strong>2. Agent Runtime Lifespan</strong></td><td style="text-align:left;">Is the workload a <strong>Model 2 stateless container/web service</strong> (rehydrating system prompt, tools, and history per HTTP turn) or a stateful worker?</td><td style="text-align:left;">Stateless multi-node agents invoke the LLM <code>3–8×</code> per user turn; prefix caching is mandatory cross-turn hydration memory.</td></tr><tr><td style="text-align:left;"><strong>3. Deployment SKU Mix</strong></td><td style="text-align:left;">Will production run <strong>Provisioned Throughput (PTU-M)</strong>, <strong>Standard (PAYG)</strong>, or <strong>PTU-M primary + Standard spillover</strong> behind APIM?</td><td style="text-align:left;">On <strong>GPT-5.6 PTU-M</strong>, explicit breakpoints are unsupported—APIM must strip breakpoint fields on the PTU leg while preserving <code>prompt_cache_key</code>.</td></tr><tr><td style="text-align:left;"><strong>4. Prefix Size &amp; Peak Concurrency</strong></td><td style="text-align:left;">Do static instructions + tool schemas exceed <strong>1,024 tokens</strong>, and does any prompt family exceed <strong>~15 RPM</strong> at peak?</td><td style="text-align:left;">Prefixes <code>&lt;1,024</code> tokens cannot cache (disable writes on 5.6+); families <code>&gt;15 RPM</code> require deterministic <code>prompt_cache_key</code> sharding (<code>N = ⌈RPM ÷ 12⌉</code>).</td></tr><tr><td style="text-align:left;"><strong>5. Existing CI &amp; Telemetry Maturity</strong></td><td style="text-align:left;">Does the team already run automated prompt evaluations (<code>pytest</code> / DeepEval / Foundry Evals) and emit OpenTelemetry spans to Application Insights?</td><td style="text-align:left;">Determines effort needed to wire <code>PCR001–006</code> static linting, 2-pass cache assertions, and the Log Analytics KQL release gate.</td></tr><tr><td style="text-align:left;"><strong>6. Ethical Walls, Chargeback &amp; Seasonal Cliffs</strong></td><td style="text-align:left;">Does the platform isolate concurrent client engagements/matters, bill tokens to <code>cost_center</code> codes, or face <code>3×–6×</code> filing/audit-close traffic surges?</td><td style="text-align:left;">Activates the <a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/profiles/regulated-multi-engagement">Regulated Multi-Engagement &amp; Compliance Profile</a>: <code>Posture A</code> zero-client-cache mode, out-of-band OTel chargeback, seasonal PTU + PAYG spillover math, and <code>C-WP1–C-WP4</code> workpaper parity gates.</td></tr></tbody></table><h2 id="_2-phased-3-week-delivery-blueprint" tabindex="-1">2. Phased 3-Week Delivery Blueprint <a class="header-anchor" href="#_2-phased-3-week-delivery-blueprint" aria-label="Permalink to &quot;2. Phased 3-Week Delivery Blueprint&quot;">​</a></h2>',3)),t[3]||(t[3]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 144",role:"img","aria-labelledby":"del-bp-title del-bp-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"del-bp-title"},"Three-Week Customer Readiness Delivery Flow"),e("desc",{id:"del-bp-desc"},"Shows 30-Minute Intake Triage leading to Week 1 Baseline Audit Report, Week 2 Refactored Middleware and APIM Policy, and Week 3 Signed C1-C15 Readiness Record and Right-Sized PTU Model."),e("defs",null,[e("marker",{id:"del-bp-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"14",width:"166",height:"90",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"16",y:"33","font-size":"9.3","font-weight":"700",fill:"#183e62"},"Intake (30 Min)"),e("text",{x:"16",y:"49","font-size":"8.2",fill:"#334e68"},"Score retiring models,"),e("text",{x:"16",y:"62","font-size":"8.2",fill:"#334e68"},"SKU mix & >15 RPM"),e("text",{x:"16",y:"75","font-size":"8.2",fill:"#334e68"},"concurrency boundaries"),e("text",{x:"16",y:"94","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[Exit: Scoped Plan]"),e("path",{d:"M174 59 H196",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#del-bp-arr)"}),e("rect",{x:"200",y:"14",width:"170",height:"90",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"208",y:"33","font-size":"9.3","font-weight":"700",fill:"#183e62"},"Week 1 · Baseline Audit"),e("text",{x:"208",y:"49","font-size":"8.2",fill:"#334e68"},"Rank nodes by RPM×Tok,"),e("text",{x:"208",y:"62","font-size":"8.2",fill:"#334e68"},"run pcr_lint.py & capture"),e("text",{x:"208",y:"75","font-size":"8.2",fill:"#334e68"},"un-tuned miss baseline"),e("text",{x:"208",y:"94","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[Exit: Audit Report]"),e("path",{d:"M370 59 H392",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#del-bp-arr)"}),e("rect",{x:"396",y:"14",width:"170",height:"90",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"404",y:"33","font-size":"9.3","font-weight":"700",fill:"#183e62"},"Week 2 · Prefix & APIM"),e("text",{x:"404",y:"49","font-size":"8.2",fill:"#334e68"},"Refactor Pos 1–6 order,"),e("text",{x:"404",y:"62","font-size":"8.2",fill:"#334e68"},"shard keys & wire 429"),e("text",{x:"404",y:"75","font-size":"8.2",fill:"#334e68"},"PAYG spillover in non-prod"),e("text",{x:"404",y:"94","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[Exit: Staging Policy]"),e("path",{d:"M566 59 H588",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#del-bp-arr)"}),e("rect",{x:"592",y:"14",width:"160",height:"90",rx:"6",fill:"#eaf4f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"600",y:"33","font-size":"9.3","font-weight":"700",fill:"#115e59"},"Week 3 · Gate Sign-Off"),e("text",{x:"600",y:"49","font-size":"8.2",fill:"#334e68"},"2-pass evals, peak load,"),e("text",{x:"600",y:"62","font-size":"8.2",fill:"#334e68"},"KQL workbook & right-sized"),e("text",{x:"600",y:"75","font-size":"8.2",fill:"#334e68"},"PTU reservation model"),e("text",{x:"600",y:"94","font-size":"7.8","font-weight":"700",fill:"#0f766e"},"[Exit: Signed C1–C15]"),e("text",{x:"10",y:"130","font-size":"8.4",fill:"#526c80"},"Each week produces one tangible engineering artifact verified before advancing to the next phase.")])],-1)),t[4]||(t[4]=a('<table tabindex="0"><thead><tr><th style="text-align:left;">Phase</th><th style="text-align:left;">Core Engineering Activities</th><th style="text-align:left;">Concrete Exit Artifact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Week 1: Baseline Audit &amp; Prefix Mapping</strong></td><td style="text-align:left;">• Inventory top prompt families / agent nodes by token volume and peak RPM.<br>• Run <code>PCR001–PCR006</code> audit for early timestamps, unsorted <code>tools[]</code>, mutated <code>response_format</code>, and unpinned <code>reasoning.context</code>.<br>• Capture baseline quality, TTFT p50/p95, and <code>cached_tokens</code> on current vs. un-tuned target model (50–200 golden cases).</td><td style="text-align:left;"><strong>1. Prefix Audit &amp; Baseline Ablation Report</strong> (quantifying un-tuned miss rate &amp; PTU exposure).</td></tr><tr><td style="text-align:left;"><strong>Week 2: Prefix Refactoring, Sharding &amp; Gateway Wiring</strong></td><td style="text-align:left;">• Refactor context assembly middleware to strict <code>Pos 1–6</code> (<code>T0 → L2 → L1 → Volatile Tail</code>) order.<br>• Add deterministic <code>prompt_cache_key</code> with <code>&gt;15 RPM</code> sharding and SKU-aware breakpoints (<code>Standard</code> / <code>GPT-6+ PTU-M</code>).<br>• Configure APIM <code>429 Retry-After</code> circuit-breaker spillover from PTU-M to Standard PAYG.</td><td style="text-align:left;"><strong>2. Refactored Context Middleware &amp; SKU-Aware APIM Policy</strong> validated in non-prod.</td></tr><tr><td style="text-align:left;"><strong>Week 3: 7-Layer Gate Verification &amp; PTU Right-Sizing</strong></td><td style="text-align:left;">• Execute 2-pass DeepEval quality + cache parity suite (<code>cached_tokens &gt;= 1024</code>, share <code>&gt;=60%</code>, <code>R/W &gt;= 10:1</code>).<br>• Run peak concurrency load test (<code>&gt;15 RPM/family</code>) verifying zero HTTP <code>429</code>s below <code>60–70%</code> PTU saturation.<br>• Deploy App Insights KQL workbook and finalize right-sized PTU reservation model.</td><td style="text-align:left;"><strong>3. Signed <code>C1–C15</code> Migration Readiness Record + Right-Sized PTU Capacity Model</strong>.</td></tr></tbody></table><h2 id="_3-workstream-ownership-boundaries" tabindex="-1">3. Workstream Ownership Boundaries <a class="header-anchor" href="#_3-workstream-ownership-boundaries" aria-label="Permalink to &quot;3. Workstream Ownership Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Workstream</th><th style="text-align:left;">Scope During the 3-Week Engagement</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Architecture &amp; Sizing</strong></td><td style="text-align:left;">Intake scorecard qualification, <code>Pos 1–6</code> prefix workshop, APIM spillover design review, and two-regime PTU sizing verification.</td></tr><tr><td style="text-align:left;"><strong>2. Application &amp; Evaluation</strong></td><td style="text-align:left;">Context middleware refactoring, canonical <code>tools[]</code> JSON serialization, and the 50–200 case golden evaluation dataset.</td></tr><tr><td style="text-align:left;"><strong>3. Gateway &amp; Observability</strong></td><td style="text-align:left;">APIM backend pool failover policy, OpenTelemetry <code>gen_ai.*</code> span attributes, DCR PII masking, and KQL alert rules.</td></tr><tr><td style="text-align:left;"><strong>4. Capacity &amp; Cost Governance</strong></td><td style="text-align:left;">Review of <code>DeployPeakNormTPM</code> vs. <code>ShardAvgNormTPM</code> telemetry and approval of Global / Data Zone PTU allocation + Standard spillover budget.</td></tr></tbody></table>',3))])}const k=d(g,[["render",p]]);export{b as __pageData,k as default};
